<style>
  :root{
    --bg:#FAF7F1;
    --bg-soft:#F3EEE3;
    --card:#FFFFFF;
    --ink:#1C1A17;
    --ink-soft:#423E37;
    --ink-faint:#595347;
    --gold:#684B1B;
    --gold-deep:#553D16;
    --gold-btn:#745218;
    --gold-btn-text:#FFFFFF;
    --gold-soft:#EFE6D2;
    --line:#E3DCCB;
    --line-strong:#CFC4A6;
    --shadow:0 10px 30px rgba(28,26,23,.08);
    --radius:10px;
    --serif:Georgia,'Iowan Old Style','Times New Roman',serif;
    --sans:-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
  }
  @media (prefers-color-scheme: dark){
    :root{
      --bg:#171410;
      --bg-soft:#1F1B15;
      --card:#211C16;
      --ink:#EDE6D6;
      --ink-soft:#D4CBBC;
      --ink-faint:#B5A894;
      --gold:#E5BE72;
      --gold-deep:#F0CE8A;
      --gold-btn:#E5BE72;
      --gold-btn-text:#171410;
      --gold-soft:#2C2517;
      --line:#37301F;
      --line-strong:#4A4028;
      --shadow:0 10px 30px rgba(0,0,0,.45);
    }
  
  }
  *{box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{
    margin:0;background:var(--bg);color:var(--ink);
    font-family:var(--sans);font-size:17px;line-height:1.65;
    -webkit-font-smoothing:antialiased;
  }
  ::selection{background:var(--gold-soft)}
  a{color:var(--gold-deep);text-decoration:none}
  a:hover{text-decoration:underline}
  h1,h2,h3{font-family:var(--serif);font-weight:600;line-height:1.2;color:var(--ink);margin:0}
  .wrap{max-width:1120px;margin:0 auto;padding:0 24px}
  .gold{color:var(--gold-deep)}
  mark{background:linear-gradient(transparent 62%, var(--gold-soft) 62%);color:inherit;padding:0 .08em}
  .btn{
    display:inline-flex;align-items:center;gap:8px;
    font-family:var(--sans);font-weight:600;font-size:14px;
    padding:9px 18px;border-radius:999px;border:1px solid var(--gold);
    background:var(--gold-btn, #745218);color:#FFF;cursor:pointer;transition:background .2s,border-color .2s,transform .15s;
  }
  .btn:hover{background:var(--gold-deep);border-color:var(--gold-deep);text-decoration:none;transform:translateY(-1px)}
  .btn-ghost{background:transparent;color:var(--ink);border-color:var(--line-strong)}
  .btn-ghost:hover{background:var(--bg-soft);border-color:var(--gold);color:var(--ink)}
  .tag{
    display:inline-block;font-size:12.5px;font-weight:600;letter-spacing:.04em;
    color:var(--gold-deep);background:var(--gold-soft);
    border:1px solid var(--line);border-radius:999px;padding:3px 11px;
  }
  .eyebrow{
    font-size:13px;font-weight:700;letter-spacing:.22em;text-transform:uppercase;
    color:var(--gold-deep);margin:0 0 18px;
  }
  .section{padding:84px 0}
  .section-soft{background:var(--bg-soft)}
  .section-head{max-width:640px;margin-bottom:44px}
  .section-head h2{font-size:clamp(28px,4vw,38px);margin-bottom:12px}
  .section-head p{color:var(--ink-soft);margin:0;font-size:18px}

  /* ---------- Header ---------- */
  header.site{
    position:sticky;top:0;z-index:60;
    background:color-mix(in srgb, var(--bg) 92%, transparent);
    backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);
    border-bottom:1px solid var(--line);
  }
  .nav{display:flex;align-items:center;justify-content:space-between;gap:16px;height:66px}
  .brand{font-family:var(--serif);font-size:20px;font-weight:700;color:var(--ink);letter-spacing:.01em}
  .brand span{color:var(--gold-deep)}
  .brand:hover{text-decoration:none}
  .nav-links{display:flex;align-items:center;gap:28px}
  .nav-links a{color:var(--ink-soft);font-size:15.5px;font-weight:500}
  .nav-links a.active{color:var(--ink);border-bottom:2px solid var(--gold);padding-bottom:2px}
  .nav-links a:hover{color:var(--ink);text-decoration:none}
  .nav-cta{padding:9px 20px;font-size:15px}
  /* standard btn active */
  .nav-links a.btn:hover, .nav-links a.nav-cta:hover{background:var(--gold-deep, #553D16);color:#FFFFFF!important}
  @media (prefers-color-scheme: dark){
    .nav-links a.btn, .nav-links a.nav-cta, a.btn{color:#171410!important;background:var(--gold-btn, #E5BE72)}
    .nav-links a.btn:hover, .nav-links a.nav-cta:hover{background:var(--gold-deep, #F0CE8A);color:#171410!important}
  }
  .lang-toggle-btn{
    display:inline-flex;align-items:center;gap:4px;padding:6px 14px;border-radius:999px;
    border:1.5px solid var(--gold);color:var(--ink)!important;font-weight:700;font-size:13.5px;
    background:var(--gold-soft);text-decoration:none!important;transition:transform .15s,background .2s;
  }
  .lang-toggle-btn:hover{transform:translateY(-1px);background:var(--card)}
  .trust-strip-hero{
    display:flex;flex-wrap:wrap;gap:12px 20px;margin-top:20px;padding:12px 18px;
    background:var(--bg-soft);border:1px solid var(--line);border-radius:10px;
    font-size:13.5px;font-weight:600;color:var(--ink);
  }
  .sticky-mobile-bar{display:none}
  @media (max-width: 720px){
    .sticky-mobile-bar{
      display:flex;gap:8px;position:fixed;left:12px;right:12px;
      bottom:calc(12px + env(safe-area-inset-bottom));z-index:90;
      box-shadow:0 10px 30px rgba(0,0,0,0.22);border-radius:999px;
      background:var(--card);padding:6px;border:1px solid var(--line-strong);
    }
    .sticky-btn-audit{flex:1.3;justify-content:center;padding:10px 14px!important;font-size:14px!important;white-space:nowrap}
    .sticky-btn-mail{flex:0.9;justify-content:center;padding:10px 14px!important;font-size:14px!important;white-space:nowrap}
    .sticky-mail{display:none!important}
  }
  .burger{display:none;background:none;border:0;cursor:pointer;padding:8px;color:var(--ink)}
  .burger svg{display:block}

  /* ---------- Views ---------- */
  .view{display:none}
  .view.active, #view-home.active{display:block;animation:viewIn .35s ease both}
  @keyframes viewIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}

  /* ---------- Hero ---------- */
  .hero{padding:72px 0 84px;border-bottom:1px solid var(--line)}
  .hero-grid{display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:center}
  .hero h1{font-size:clamp(36px,5.2vw,56px);letter-spacing:-.01em;margin-bottom:20px}
  .hero .sub{font-size:19px;color:var(--ink-soft);margin:0 0 30px;max-width:520px}
  .hero-ctas{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:26px}
  .trust-line{font-size:14.5px;color:var(--ink-faint);display:flex;flex-wrap:wrap;gap:6px 14px;align-items:center}
  .trust-line .dot{width:4px;height:4px;border-radius:50%;background:var(--gold);display:inline-block}

  /* Cinematic motion visual (the reel, as a live page element) */
  .motion{
    position:relative;border:1px solid var(--line);border-radius:14px;
    background:var(--card);box-shadow:var(--shadow);overflow:hidden;
  }
  .motion-bar{
    display:flex;align-items:center;gap:6px;padding:11px 14px;
    border-bottom:1px solid var(--line);background:var(--bg-soft);
  }
  .motion-bar i{width:10px;height:10px;border-radius:50%;background:var(--line-strong);display:block}
  .motion-bar i:first-child{background:var(--gold)}
  .motion-bar em{font-style:normal;margin-left:8px;font-size:12.5px;color:var(--ink-faint);letter-spacing:.03em}
  .motion-stage{position:relative;padding:22px 22px 18px;min-height:300px}
  .phone{
    width:172px;margin:0 auto;border:2px solid var(--ink);border-radius:24px;
    padding:10px 10px 14px;background:var(--bg);position:relative;z-index:2;
  }
  .phone .notch{width:52px;height:5px;border-radius:3px;background:var(--line-strong);margin:0 auto 10px}
  .phone .p-img{height:86px;border-radius:8px;background:linear-gradient(135deg,var(--gold-soft),var(--line))}
  .phone .p-line{height:8px;border-radius:4px;background:var(--line);margin-top:9px}
  .phone .p-line.short{width:62%}
  .phone .p-btn{
    margin-top:12px;height:30px;border-radius:999px;background:var(--gold);
    color:#fff;font-size:12px;font-weight:700;display:flex;align-items:center;justify-content:center;
    animation:pulseBtn 2.4s ease-in-out infinite;
  }
  @keyframes pulseBtn{0%,100%{transform:scale(1)}50%{transform:scale(1.045)}}
  .gauge{width:220px;margin:16px auto 0;text-align:center}
  .gauge svg{width:100%;height:auto;display:block}
  .needle{transform-origin:110px 104px;animation:needleSweep 5s ease-in-out infinite}
  @keyframes needleSweep{0%,12%{transform:rotate(-58deg)}38%,78%{transform:rotate(52deg)}100%{transform:rotate(-58deg)}}
  .gauge-label{font-size:13px;color:var(--ink-faint);margin-top:2px}
  .gauge-label b{color:var(--gold-deep)}
  .chip{
    position:absolute;z-index:3;background:var(--card);border:1px solid var(--line-strong);
    border-radius:999px;padding:6px 13px;font-size:13px;font-weight:600;color:var(--ink);
    box-shadow:var(--shadow);display:flex;align-items:center;gap:7px;white-space:nowrap;
  }
  .chip .tick{color:var(--gold-deep);font-weight:800}
  .chip-a{top:34px;left:14px;animation:floaty 5s ease-in-out infinite}
  .chip-b{top:118px;right:12px;animation:floaty 6s ease-in-out .8s infinite}
  .chip-c{bottom:96px;left:10px;animation:floaty 5.5s ease-in-out 1.6s infinite}
  @keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
  .loadbar{height:6px;border-radius:3px;background:var(--line);overflow:hidden;margin:14px auto 0;max-width:320px}
  .loadbar i{display:block;height:100%;width:34%;border-radius:3px;background:var(--gold);animation:loadFill 5s ease-in-out infinite}
  @keyframes loadFill{0%,12%{width:34%}38%,78%{width:96%}100%{width:34%}}
  .motion-cap{padding:0 22px 20px;text-align:center;font-size:14px;color:var(--ink-faint)}
  .motion-cap b{color:var(--ink)}
  @media (prefers-reduced-motion: reduce){
    .needle,.loadbar i,.chip,.phone .p-btn{animation:none}
    .needle{transform:rotate(30deg)}
    .loadbar i{width:88%}
  }

  /* ---------- Cards / grids ---------- */
  .grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
  .card{
    background:var(--card);border:1px solid var(--line);border-radius:var(--radius);
    padding:28px 26px;display:flex;flex-direction:column;gap:12px;
    transition:border-color .2s, box-shadow .2s;
  }
  .card:hover{border-color:var(--line-strong);box-shadow:var(--shadow)}
  .card h3{font-size:21px}
  .card p{margin:0;color:var(--ink-soft);font-size:16px}
  .card .more{margin-top:auto;font-weight:600;font-size:15.5px}
  .card .tag{align-self:flex-start}
  .work-card .w-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
  .work-card h3 a{color:var(--ink)}
  .work-card h3 a:hover{color:var(--gold-deep)}
  .visit{font-size:14.5px;font-weight:600}
  .card-media{margin:-28px -26px 2px;overflow:hidden;border-bottom:1px solid var(--line);background:var(--bg-soft)}
  .card-media img{display:block;width:100%;height:210px;object-fit:cover}

  /* ---------- Process ---------- */
  .steps{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
  .step{border-top:2px solid var(--gold);padding-top:18px}
  .step .n{font-family:var(--serif);font-size:15px;color:var(--gold-deep);font-weight:700;letter-spacing:.08em}
  .step h3{font-size:19px;margin:8px 0 8px}
  .step p{margin:0;color:var(--ink-soft);font-size:15.5px}

  /* ---------- About ---------- */
  .about-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:48px;align-items:start}
  .about-grid p{color:var(--ink-soft);margin:0 0 16px;font-size:17.5px}
  .facts{border:1px solid var(--line);border-radius:var(--radius);background:var(--card);padding:24px 26px}
  .facts dl{margin:0;display:grid;gap:14px}
  .facts dt{font-size:12.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--ink-faint)}
  .facts dd{margin:2px 0 0;font-size:16.5px;font-weight:600;color:var(--ink)}

  /* ---------- FAQ ---------- */
  .faq{max-width:760px}
  details.faq-item{border-bottom:1px solid var(--line);padding:6px 0}
  details.faq-item summary{
    cursor:pointer;font-family:var(--serif);font-size:19px;font-weight:600;
    padding:10px 20px 14px 0;list-style:none;position:relative;color:var(--ink);
  }
  details.faq-item summary::-webkit-details-marker{display:none}
  details.faq-item summary::after{
    content:"+";position:absolute;right:2px;top:12px;font-size:24px;color:var(--gold-deep);font-family:var(--sans);font-weight:400;
  }
  details.faq-item[open ] summary::after{content:"–"}
  details.faq-item p{margin:0 0 16px;color:var(--ink-soft);max-width:680px}

  /* ---------- CTA block ---------- */
  .cta-block{
    border:1px solid var(--line-strong);border-radius:14px;background:var(--bg-soft);
    padding:52px 40px;text-align:center;
  }
  .cta-block h2{font-size:clamp(26px,3.6vw,36px);margin-bottom:12px}
  .cta-block p{color:var(--ink-soft);margin:0 auto 26px;max-width:520px;font-size:17.5px}
  .cta-mail{font-family:var(--serif);font-size:clamp(20px,3vw,26px)}

  /* ---------- Services page ---------- */
  .page-head{padding:64px 0 10px}
  .page-head h1, .page-head h2{font-size:clamp(32px,4.6vw,46px);margin-bottom:14px;max-width:720px;line-height:1.2;font-family:var(--serif);font-weight:700}
  .page-head p{color:var(--ink-soft);font-size:18.5px;max-width:640px;margin:0}
  .service-block{
    display:grid;grid-template-columns:.9fr 1.1fr;gap:44px;padding:52px 0;
    border-bottom:1px solid var(--line);align-items:start;
  }
  .service-block:last-of-type{border-bottom:0}
  .service-block h2{font-size:clamp(26px,3.4vw,34px);margin-bottom:12px}
  .service-block .lead{color:var(--ink-soft);font-size:17.5px;margin:0 0 18px}
  .service-block ul{margin:0 0 20px;padding:0;list-style:none}
  .service-block li{padding:7px 0 7px 30px;position:relative;color:var(--ink-soft);border-bottom:1px dashed var(--line)}
  .service-block li:last-child{border-bottom:0}
  .service-block li::before{content:"✓";position:absolute;left:2px;color:var(--gold-deep);font-weight:800}
  .service-block li b{color:var(--ink)}
  .who-for{background:var(--bg-soft);border:1px solid var(--line);border-radius:var(--radius);padding:20px 22px}
  .who-for h3{font-size:16px;font-family:var(--sans);font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--gold-deep);margin-bottom:8px}
  .who-for p{margin:0;color:var(--ink-soft);font-size:16px}

  /* ---------- Blog ---------- */
  .blog-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
  .post-card .p-cat{font-size:12.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--gold-deep)}
  .post-card h3{font-size:20px;line-height:1.35}
  .post-card h3 a{color:var(--ink)}
  .post-card h3 a:hover{color:var(--gold-deep)}
  .post-meta{font-size:14px;color:var(--ink-faint)}
  .post-card .card-media img{height:180px}
  .article-hero{display:block;width:100%;aspect-ratio:16/8;object-fit:cover;border:1px solid var(--line);border-radius:12px;margin:0 0 34px;background:var(--bg-soft)}
  .article-wrap{max-width:760px;margin:0 auto;padding:56px 24px 84px}
  .article-wrap .back{font-size:15px;font-weight:600}
  .article-wrap h1{font-size:clamp(30px,4.4vw,42px);margin:18px 0 10px}
  .article-meta{color:var(--ink-faint);font-size:15px;margin-bottom:34px}
  .article-body h2{font-size:27px;margin:38px 0 12px}
  .article-body h3{font-size:21px;margin:28px 0 10px}
  .article-body p{color:var(--ink-soft);margin:0 0 18px;font-size:17.5px}
  .article-body ul,.article-body ol{color:var(--ink-soft);margin:0 0 18px;padding-left:24px}
  .article-body li{margin-bottom:8px;font-size:17.5px}
  .article-body strong{color:var(--ink)}
  .article-body code{
    font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.92em;
    background:var(--bg-soft);border:1px solid var(--line);border-radius:5px;padding:1px 6px;color:var(--ink);
  }
  .article-cta{
    margin-top:44px;border:1px solid var(--line-strong);border-radius:12px;
    background:var(--bg-soft);padding:28px;text-align:center;
  }
  .article-cta p{margin:0 0 16px;font-family:var(--serif);font-size:20px;color:var(--ink)}

  /* ---------- Watch ---------- */
  .watch-grid{display:grid;grid-template-columns:1fr 360px;gap:56px;align-items:center;padding:10px 0 84px}
  .watch-copy h2{font-size:clamp(25px,3.4vw,34px);margin:34px 0 12px}
  .watch-copy p{color:var(--ink-soft);font-size:17.5px;max-width:560px}
  .watch-copy ul{margin:22px 0 0;padding:0;list-style:none;max-width:560px}
  .watch-copy li{padding:9px 0 9px 30px;position:relative;color:var(--ink-soft);border-bottom:1px dashed var(--line)}
  .watch-copy li::before{content:"✓";position:absolute;left:2px;color:var(--gold-deep);font-weight:800}
  .reel-phone{
    width:min(340px,100%);aspect-ratio:9/18.2;margin:0 auto;padding:11px;
    border:2px solid var(--ink);border-radius:40px;background:#14110d;
    box-shadow:0 24px 55px rgba(28,26,23,.25);
  }
  .reel-screen{
    position:relative;height:100%;overflow:hidden;border-radius:30px;
    background:linear-gradient(160deg,var(--gold-soft),var(--bg-soft) 48%,var(--card));
    display:flex;align-items:center;justify-content:center;
  }
  .reel-screen::before{
    content:"";position:absolute;width:58%;height:5px;border-radius:99px;
    background:rgba(255,255,255,.28);top:10px;left:21%;z-index:4;
  }
  .reel-screen video{
    position:absolute;inset:0;width:100%;height:100%;object-fit:cover;background:#000;
    opacity:0;pointer-events:none;z-index:2;
  }
  .reel-screen video.ready{opacity:1;pointer-events:auto}
  .reel-placeholder{
    position:relative;z-index:3;text-align:center;padding:34px 26px;color:var(--ink);
  }
  .reel-placeholder .reel-kicker{font-size:12.5px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;color:var(--gold-deep);margin:0 0 12px}
  .reel-placeholder h2{font-size:30px;margin-bottom:12px}
  .reel-placeholder p{color:var(--ink-soft);font-size:16px;margin:0 auto 22px;max-width:230px}
  .reel-play{
    width:68px;height:68px;border-radius:50%;border:1px solid var(--gold);
    background:var(--gold);color:#fff;font-size:25px;cursor:pointer;
    display:inline-flex;align-items:center;justify-content:center;padding-left:4px;
    box-shadow:0 12px 26px rgba(28,26,23,.22);
  }
  .reel-play:hover{background:var(--gold-deep)}
  .reel-status{font-size:14px!important;margin-top:18px!important}
  .watch-teaser{border-top:1px solid var(--line);padding:0 0 72px;display:flex;align-items:center;justify-content:space-between;gap:24px}
  .watch-teaser h2{font-size:26px;margin-bottom:6px}
  .watch-teaser p{margin:0;color:var(--ink-soft)}

  /* ---------- Contact ---------- */
  .contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start;padding-bottom:84px}
  form.req{display:grid;gap:18px}
  .field label{display:block;font-weight:600;font-size:15px;margin-bottom:6px}
  .field input,.field select,.field textarea{
    width:100%;padding:12px 14px;font:inherit;font-size:16px;color:var(--ink);
    background:var(--card);border:1px solid var(--line-strong);border-radius:8px;
  }
  .field textarea{min-height:130px;resize:vertical}
  .field ::placeholder{color:var(--ink-faint);opacity:1}
  input:focus,.field select:focus,.field textarea:focus{
    outline:2px solid var(--gold);outline-offset:1px;border-color:var(--gold);
  }
  .form-note{font-size:14.5px;color:var(--ink-faint);margin:0}
  .contact-side h2{font-size:26px;margin-bottom:12px}
  .contact-side p{color:var(--ink-soft);margin:0 0 18px}
  .big-mail{
    display:block;text-align:center;font-family:var(--serif);font-size:clamp(19px,2.6vw,24px);
    border:1px solid var(--gold);border-radius:12px;padding:22px;background:var(--gold-soft);
    color:var(--ink);margin-bottom:14px;word-break:break-all;
  }
  .big-mail:hover{text-decoration:none;border-color:var(--gold-deep)}
  .reply-note{display:flex;gap:10px;align-items:flex-start;color:var(--ink-soft);font-size:16px}
  .reply-note .tick{color:var(--gold-deep);font-weight:800}

  /* ---------- Footer ---------- */
  footer.site{border-top:1px solid var(--line);padding:38px 0 46px;background:var(--bg-soft)}
  .foot{display:flex;flex-wrap:wrap;gap:14px 32px;justify-content:space-between;align-items:center}
  .foot p{margin:0;color:var(--ink-faint);font-size:14.5px}
  .foot nav{display:flex;gap:22px;flex-wrap:wrap}
  .foot nav a{color:var(--ink-soft);font-size:14.5px;font-weight:500}

  /* ---------- Sticky mobile email ---------- */
  .sticky-mail{
    display:none;position:fixed;left:16px;right:16px;bottom:calc(14px + env(safe-area-inset-bottom));z-index:70;
    text-align:center;box-shadow:0 12px 28px rgba(28,26,23,.28);
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 960px){
    .hero-grid{grid-template-columns:1fr;gap:40px}
    .grid-3,.blog-grid{grid-template-columns:1fr 1fr}
    .steps{grid-template-columns:1fr 1fr}
    .about-grid,.service-block,.contact-grid,.watch-grid{grid-template-columns:1fr}
    .watch-grid{gap:38px}
    .service-block{gap:24px}
  }
  @media (max-width: 720px){
    body{font-size:16px}
    .section{padding:60px 0}
    .hero{padding:48px 0 60px}
    .nav-links{
      display:none;position:absolute;top:66px;left:0;right:0;
      background:var(--bg);border-bottom:1px solid var(--line);
      flex-direction:column;align-items:flex-start;gap:0;padding:10px 24px 18px;
    }
    .nav-links.open{display:flex}
    .nav-links a{padding:10px 0;width:100%}
    .nav-links .nav-cta{margin-top:8px}
    .burger{display:block}
    .grid-3,.blog-grid,.steps{grid-template-columns:1fr}
    .watch-teaser{align-items:flex-start;flex-direction:column;padding-bottom:58px}
    .reel-phone{width:min(320px,100%)}
    .chip-c{display:none}
    .chip-a{left:6px}.chip-b{right:6px}
    .sticky-mail{display:inline-flex;justify-content:center}
    body{padding-bottom:76px}
    .cta-block{padding:40px 24px}
  }

  /* ---------- Video Audit & Responsive Forms ---------- */
  .audit-card-box {
    max-width:820px;margin:0 auto;background:var(--card);border:2px solid var(--gold);
    border-radius:18px;padding:36px 32px;box-shadow:0 12px 36px rgba(0,0,0,0.06);position:relative;
    box-sizing:border-box;
  }
  .audit-grid-row {
    display:grid;grid-template-columns:1fr 1fr;gap:16px;
  }
  .audit-top-badge {
    position:absolute;top:-13px;left:50%;transform:translateX(-50%);
    background:var(--gold-btn, #745218);color:#FFF;padding:4px 18px;border-radius:999px;
    font-size:12px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap;
    box-shadow:0 2px 8px rgba(0,0,0,0.15);
  }
  .review-grid, .pricing-grid {
    display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:24px;
  }
  .review-card, .pricing-card {
    background:var(--card);border:1px solid var(--line);border-radius:14px;padding:28px 24px;
    box-shadow:0 6px 20px rgba(0,0,0,0.04);display:flex;flex-direction:column;justify-content:space-between;
    box-sizing:border-box;
  }
  @media (max-width: 680px) {
    .audit-card-box { padding:24px 16px !important; border-radius:14px !important; margin:0 4px !important; }
    .audit-grid-row { grid-template-columns:1fr !important; gap:12px !important; }
    .audit-top-badge { font-size:10.5px !important; padding:3px 12px !important; top:-11px !important; }
    .review-grid, .pricing-grid { grid-template-columns:1fr !important; gap:18px !important; }
    .field input, .field select, .field textarea,
    #auditFormEN input, #auditFormEN select,
    #auditFormNL input, #auditFormNL select,
    #dutchContactForm input, #dutchContactForm select, #dutchContactForm textarea {
      font-size:16px !important; /* Disables unwanted iOS Safari zoom */
      padding:12px 14px !important;
      border-radius:8px !important;
      width:100% !important;
      box-sizing:border-box !important;
    }
    #auditSubmitBtnEN, #auditSubmitBtnNL, #contactSubmitBtn, #nl-submit-btn {
      width:100% !important;
      max-width:320px !important;
      margin:0 auto !important;
      display:flex !important;
      justify-content:center !important;
      padding:10px 18px !important;
      font-size:14px !important;
      font-weight:700 !important;
      border-radius:8px !important;
      text-align:center !important;
    }
  }


  /* Floating Sticky WhatsApp Highlight Button */
  .whatsapp-float{
    position:fixed;
    bottom:28px;
    right:28px;
    z-index:999;
    display:inline-flex;
    align-items:center;
    gap:10px;
    background:#25D366;
    color:#FFFFFF!important;
    padding:10px 20px 10px 14px;
    border-radius:999px;
    font-size:14.5px;
    font-weight:700;
    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
    text-decoration:none!important;
    box-shadow:0 8px 24px rgba(37,211,102,.45),0 2px 8px rgba(0,0,0,.18);
    transition:transform .2s ease,box-shadow .2s ease;
  }
  .whatsapp-float:hover{
    transform:scale(1.05) translateY(-2px);
    box-shadow:0 12px 30px rgba(37,211,102,.6),0 4px 12px rgba(0,0,0,.22);
    color:#FFFFFF!important;
  }
  .whatsapp-float svg{
    width:24px;
    height:24px;
    flex-shrink:0;
    fill:#FFFFFF;
  }
  .whatsapp-float .wa-pulse{
    position:absolute;
    inset:-3px;
    border-radius:999px;
    border:2px solid #25D366;
    animation:waPulse 2.4s infinite ease-out;
    pointer-events:none;
  }
  @keyframes waPulse{
    0%{transform:scale(1);opacity:.8}
    70%{transform:scale(1.12,1.25);opacity:0}
    100%{transform:scale(1.12,1.25);opacity:0}
  }
  @media(max-width:720px){
    .whatsapp-float{
      bottom:76px;
      right:16px;
      padding:0;
      width:52px;
      height:52px;
      justify-content:center;
      border-radius:50%;
    }
    .whatsapp-float .wa-text{display:none}
    .whatsapp-float svg{width:28px;height:28px}
    .whatsapp-float .wa-pulse{
      inset:-4px;
      border-radius:50%;
    }
    @keyframes waPulse{
      0%{transform:scale(1);opacity:.8}
      70%{transform:scale(1.25);opacity:0}
      100%{transform:scale(1.25);opacity:0}
    }
  }


  /* ============================================================
     PREMIUM BUTTON SYSTEM: High Contrast, Tactile Press, Rich Hover
     ============================================================ */
  .btn, a.btn, button.btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    font-family: var(--sans);
    font-weight: 700;
    font-size: 14.5px;
    line-height: 1.2;
    padding: 10px 22px;
    border-radius: 999px;
    border: 1.5px solid var(--gold);
    background: var(--gold-btn, #E5BE72);
    color: var(--gold-btn-text, #171410) !important;
    text-decoration: none !important;
    cursor: pointer;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12);
    transition: transform 0.15s cubic-bezier(0.4, 0, 0.2, 1),
                box-shadow 0.2s ease,
                background 0.2s ease,
                border-color 0.2s ease,
                color 0.2s ease;
    -webkit-tap-highlight-color: transparent;
    user-select: none;
  }

  /* Hover State: Smooth lift + warm golden glow */
  .btn:hover, a.btn:hover, button.btn:hover {
    transform: translateY(-2px);
    background: var(--gold-deep, #F0CE8A) !important;
    border-color: var(--gold-deep, #F0CE8A) !important;
    color: var(--gold-btn-text, #171410) !important;
    box-shadow: 0 8px 24px rgba(229, 190, 114, 0.4) !important;
    text-decoration: none !important;
  }

  /* Active / Click State: Tactile depression feedback (User feels button pressed!) */
  .btn:active, a.btn:active, button.btn:active {
    transform: translateY(1.5px) scale(0.98) !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.3) !important;
    transition-duration: 0.04s !important;
  }

  /* Focus Visible for Accessibility */
  .btn:focus-visible, a.btn:focus-visible, button.btn:focus-visible {
    outline: 2px solid var(--gold);
    outline-offset: 3px;
  }

  /* Ghost / Secondary Button (e.g., 'See 3 Live Projects') - Crystal Clear Contrast */
  .btn-ghost, a.btn-ghost, a.btn.btn-ghost,
  .btn-outline, a.btn-outline, a.btn.btn-outline {
    background: transparent !important;
    border: 1.5px solid var(--line-strong, #4A4028) !important;
    color: var(--ink, #EDE6D6) !important;
    box-shadow: none !important;
  }

  /* Ghost Hover State */
  .btn-ghost:hover, a.btn-ghost:hover, a.btn.btn-ghost:hover,
  .btn-outline:hover, a.btn-outline:hover, a.btn.btn-outline:hover {
    background: var(--gold-soft, #2C2517) !important;
    border-color: var(--gold, #E5BE72) !important;
    color: var(--gold, #E5BE72) !important;
    box-shadow: 0 6px 20px rgba(229, 190, 114, 0.25) !important;
    transform: translateY(-2px);
  }

  /* Ghost Active State */
  .btn-ghost:active, a.btn-ghost:active, a.btn.btn-ghost:active,
  .btn-outline:active, a.btn-outline:active, a.btn.btn-outline:active {
    transform: translateY(1.5px) scale(0.98) !important;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.2) !important;
    transition-duration: 0.04s !important;
  }

  /* WhatsApp Floating & Header Buttons */
  a[href*="wa.me"].btn, .whatsapp-btn {
    background: #25D366 !important;
    border-color: #25D366 !important;
    color: #FFFFFF !important;
  }
  a[href*="wa.me"].btn:hover, .whatsapp-btn:hover {
    background: #20ba59 !important;
    border-color: #20ba59 !important;
    box-shadow: 0 8px 24px rgba(37, 211, 102, 0.4) !important;
  }
  a[href*="wa.me"].btn:active, .whatsapp-btn:active {
    transform: translateY(1.5px) scale(0.98) !important;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25) !important;
  }

</style>
