var descEl = document.querySelector('meta[name="description"]');

function setMeta(view, article){
  if (view === 'home' || !view){
    // Preserve exact server-rendered title & description for the homepage!
    return;
  }
  var m;
  if (view === 'article' && article){
    m = { title: article.title + " | Jay Lakum", desc: article.excerpt };
  } else {
    m = META[view] || META.home;
  }
  document.title = m.title;
  if (descEl) descEl.setAttribute('content', m.desc);
}

/* ---------- Router ---------- */
var VIEWS = ['home','services','work','watch','blog','article','contact'];
function route(){
  var hash = (location.hash || '#home').replace(/^#\/?/, '');
  var parts = hash.split('/');
  var view = 'home', article = null;
  if (parts[0] === 'blog' && parts[1]){
    article = null;
    for (var i = 0; i < ARTICLES.length; i++){
      if (ARTICLES[i].slug === parts[1]) article = ARTICLES[i];
    }
    view = article ? 'article' : 'blog';
  } else if (VIEWS.indexOf(parts[0]) > -1 && parts[0] !== 'article'){
    view = parts[0];
  }
  for (var j = 0; j < VIEWS.length; j++){
    var el = document.getElementById('view-' + VIEWS[j]);
    if (el) el.classList.toggle('active', VIEWS[j] === view);
  }
  var navKey = (view === 'article') ? 'blog' : view;
  var links = document.querySelectorAll('[data-nav]');
  for (var k = 0; k < links.length; k++){
    links[k].classList.toggle('active', links[k].getAttribute('data-nav') === navKey);
  }
  if (view === 'article' && article){
    document.getElementById('articleContent').innerHTML =
      '<h1>' + article.title + '</h1>' +
      '<p class="article-meta">' + article.category + ' · ' + article.date + ' · ' + article.read + ' · by Jay Lakum</p>' +
